#[test]
fn tag_list_replace_untag() {
    let mut h = setup();
    assert_eq!(tags(&mut h), json!({}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1", "B": ""}}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "2", "c": "é"}}));
    assert_eq!(tags(&mut h), json!({"a": "2", "B": "", "c": "é"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "zzz", "b"]}));
    assert_eq!(tags(&mut h), json!({"B": "", "c": "é"}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {}}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
    assert_eq!(tags(&mut h), json!({"B": "", "c": "é"}));
}

#[test]
fn validation_and_check_order() {
    let mut h = setup();
    let t = |tags: serde_json::Value| json!({"Command": "TagQueue", "QueueName": "q", "Tags": tags});
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": null})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    for bad in [json!([]), json!("x"), json!({"": "v"}), json!({"a b": "v"}), json!({"a": 1}), json!({"a": null}),
        json!({"k".repeat(129): "v"}), json!({"a": "x".repeat(257)}), json!({"a": "é".repeat(129)})] {
        assert_eq!(h.err(t(bad.clone())), "InvalidParameterValue", "{bad}");
    }
    h.ok(t(json!({"k".repeat(128): "x".repeat(256), "b": "é".repeat(128)})));
    for bad in [json!({}), json!("a"), json!([1]), json!([""]), json!(["a b"])] {
        assert_eq!(
            h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": bad})),
            "InvalidParameterValue",
            "{bad}"
        );
    }
