            {"Id": "a", "Body": "one"},
            {"Id": "b"},
            {"Id": "c", "Body": "three", "DelaySeconds": 10},
            {"Id": "d", "Body": "four", "DelaySeconds": 901},
            {"Id": "e", "Body": "five", "GroupId": "g"},
            {"Id": "f", "Body": "six", "Extra": 1, "DelaySeconds": null},
        ]),
    ));
    assert_eq!(
        r["Successful"],
        json!([
            {"Id": "a", "MessageId": "m-1"},
            {"Id": "c", "MessageId": "m-2"},
            {"Id": "f", "MessageId": "m-3"},
