        for bad_id in [json!(5), json!(null), json!(""), json!("a b"), json!("x".repeat(81))] {
            assert_eq!(
                h.err(c(json!("q"), json!([{"Id": bad_id, "Body": "x"}]))),
                "InvalidBatchEntryId"
            );
        }
