            assert_eq!(h.err(c(json!("q"), json!([bad_entry]))), "InvalidBatchEntryId");
        }
        // Bad id comes before duplicate ids.
        assert_eq!(
            h.err(c(json!("q"), json!([{"Id": "a"}, {"Id": "a"}, {"Id": 1}]))),
            "InvalidBatchEntryId"
        );
        assert_eq!(
            h.err(c(json!("q"), json!([{"Id": "a"}, {"Id": "b"}, {"Id": "a"}]))),
            "BatchEntryIdsNotDistinct"
        );
    }
