    let ten: Vec<Value> = (0..10).map(|i| json!({"Id": format!("{i}").repeat(8), "Body": "x"})).collect();
    let r = h.ok(send_batch("q", json!(ten)));
    assert_eq!(r["Successful"].as_array().unwrap().len(), 10);
    h.ok(send_batch("q", json!([{"Id": "x".repeat(80), "Body": "x"}])));
}

